<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { RefreshRight, Search } from '@element-plus/icons-vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import request, { apiRequest } from '../api/request';
interface Plan{id:string;name:string;enabled:boolean;sortOrder:number;monthlyPriceCents:number;priceCents:number;billingCycles:Array<'MONTHLY'|'YEARLY'>;quoteOnly:boolean}
interface Item{id:string;tenant:{id:string;name:string};plan:Plan;status:string;billingCycle:string;startedAt:string;expiresAt:string;graceEndsAt:string;baseDeviceLimit:number;basePointLimit:number;baseScadaProjectLimit:number;baseUserLimit:number;addonDeviceLimit:number;addonPointLimit:number;addonScadaProjectLimit:number;addonUserLimit:number;usage:Record<string,number>}
const items=ref<Item[]>([]),plans=ref<Plan[]>([]),loading=ref(false),keyword=ref(''),status=ref('');
const dialogVisible=ref(false),upgrading=ref<Item>(),targetPlanId=ref(''),billingCycle=ref<'MONTHLY'|'YEARLY'>('YEARLY'),voucher=ref<File>(),paidBy=ref(''),paymentReference=ref(''),submitting=ref(false);
const statusName:Record<string,string>={ACTIVE:'生效中',GRACE:'宽限期',EXPIRED:'已到期',SUSPENDED:'已暂停'};const statusType=(v:string)=>v==='ACTIVE'?'success':v==='GRACE'?'warning':'danger';const date=(v:string)=>new Date(v).toLocaleDateString('zh-CN');const effective=(base:number,addon:number)=>base===0?'不限':(base+addon).toLocaleString();const money=(value:number)=>`¥${(value/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;
const filtered=computed(()=>items.value.filter(item=>(!status.value||item.status===status.value)&&(!keyword.value.trim()||`${item.tenant.name} ${item.plan.name}`.toLowerCase().includes(keyword.value.trim().toLowerCase()))));
const upgradePlans=computed(()=>{const current=upgrading.value?.plan;return plans.value.filter(plan=>plan.enabled&&!plan.quoteOnly&&plan.id!==current?.id&&(!current||plan.sortOrder>current.sortOrder||plan.priceCents>current.priceCents||plan.monthlyPriceCents>current.monthlyPriceCents))});
const targetPlan=computed(()=>plans.value.find(plan=>plan.id===targetPlanId.value));const amount=computed(()=>billingCycle.value==='MONTHLY'?(targetPlan.value?.monthlyPriceCents||0):(targetPlan.value?.priceCents||0));
async function load(){loading.value=true;try{[items.value,plans.value]=await Promise.all([apiRequest<Item[]>({url:'/api/subscriptions/customers',method:'GET'}),apiRequest<Plan[]>({url:'/api/subscriptions/plans',method:'GET'})])}finally{loading.value=false}}
function openUpgrade(item:Item){upgrading.value=item;targetPlanId.value='';billingCycle.value=item.billingCycle==='MONTHLY'?'MONTHLY':'YEARLY';voucher.value=undefined;paidBy.value='';paymentReference.value='';dialogVisible.value=true}
function selectTargetPlan(){const cycles=targetPlan.value?.billingCycles||['YEARLY'];if(!cycles.includes(billingCycle.value))billingCycle.value=cycles[0]}
function pick(event:Event){voucher.value=(event.target as HTMLInputElement).files?.[0]}
async function submitUpgrade(){if(!upgrading.value||!targetPlanId.value)return ElMessage.warning('请选择目标套餐');if(amount.value>0&&!voucher.value)return ElMessage.warning('请上传付款凭证');submitting.value=true;try{const data=new FormData();data.append('orderType','UPGRADE');data.append('targetPlanId',targetPlanId.value);data.append('billingCycle',billingCycle.value);if(paidBy.value.trim())data.append('paidBy',paidBy.value.trim());if(paymentReference.value.trim())data.append('paymentReference',paymentReference.value.trim());if(voucher.value)data.append('voucher',voucher.value);await request.post(`/api/subscriptions/customers/${upgrading.value.tenant.id}/orders`,data,{headers:{'Content-Type':'multipart/form-data'},timeout:30000});ElMessage.success('升级订单已提交，请前往财务审核');dialogVisible.value=false;await load()}finally{submitting.value=false}}
async function showCleanupImpact(item:Item){const report=await apiRequest<{affectedRows:number;retention:{label:string;cleanupCutoffAt:string;cleanupGraceDays:number};cleanupEnabled:boolean}>({url:`/api/subscriptions/customers/${item.tenant.id}/history-cleanup-impact`,method:'GET'});await ElMessageBox.alert(`历史保存：${report.retention.label}\n清理宽限：${report.retention.cleanupGraceDays}天\n进入清理范围：${report.affectedRows.toLocaleString()}条\n清理边界：${new Date(report.retention.cleanupCutoffAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}\n自动清理：${report.cleanupEnabled?'已配置开启，仍受启动宽限限制':'未开启'}\n这里只统计，不删除数据。`,`${item.tenant.name} · 清理影响统计`,{confirmButtonText:'知道了'});}
onMounted(load);
</script>
<template><div><div class="page-actions"><div><h1 class="page-title">客户订阅</h1><p class="page-description">查看所有租户的套餐、订阅状态、有效期与资源使用情况</p></div><el-button :icon="RefreshRight" @click="load">刷新状态</el-button></div><section class="table-panel"><div class="toolbar"><el-input v-model="keyword" clearable :prefix-icon="Search" placeholder="搜索租户或套餐"/><el-select v-model="status" clearable placeholder="全部状态"><el-option label="生效中" value="ACTIVE"/><el-option label="宽限期" value="GRACE"/><el-option label="已到期" value="EXPIRED"/></el-select></div><el-table v-loading="loading" :data="filtered" empty-text="暂无客户订阅"><el-table-column label="租户" min-width="170"><template #default="{row}"><b>{{row.tenant.name}}</b></template></el-table-column><el-table-column label="套餐" min-width="130"><template #default="{row}">{{row.plan.name}}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusName[row.status]}}</el-tag></template></el-table-column><el-table-column label="订阅周期" width="100"><template #default="{row}">{{row.billingCycle==='MONTHLY'?'月付':'年付'}}</template></el-table-column><el-table-column label="有效期" min-width="190"><template #default="{row}">{{date(row.startedAt)}} 至 {{date(row.expiresAt)}}</template></el-table-column><el-table-column label="设备" width="120"><template #default="{row}">{{row.usage.devices}} / {{effective(row.baseDeviceLimit,row.addonDeviceLimit)}}</template></el-table-column><el-table-column label="点位" width="135"><template #default="{row}">{{row.usage.points}} / {{effective(row.basePointLimit,row.addonPointLimit)}}</template></el-table-column><el-table-column label="组态" width="110"><template #default="{row}">{{row.usage.scadaProjects}} / {{effective(row.baseScadaProjectLimit,row.addonScadaProjectLimit)}}</template></el-table-column><el-table-column label="用户" width="110"><template #default="{row}">{{row.usage.users}} / {{effective(row.baseUserLimit,row.addonUserLimit)}}</template></el-table-column><el-table-column label="宽限截止" min-width="130"><template #default="{row}">{{date(row.graceEndsAt)}}</template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openUpgrade(row)">升级版本</el-button><el-button link type="primary" @click="showCleanupImpact(row)">清理影响</el-button></template></el-table-column></el-table></section>
<el-dialog v-model="dialogVisible" title="为客户升级版本" width="560px"><div class="upgrade-summary"><span>客户</span><b>{{upgrading?.tenant.name}}</b><span>当前套餐</span><b>{{upgrading?.plan.name}}</b><span>目标套餐</span><el-select v-model="targetPlanId" placeholder="请选择更高版本套餐" @change="selectTargetPlan"><el-option v-for="plan in upgradePlans" :key="plan.id" :label="plan.name" :value="plan.id"/></el-select><span>订阅周期</span><el-radio-group v-model="billingCycle"><el-radio-button v-if="targetPlan?.billingCycles.includes('MONTHLY')" value="MONTHLY">月付</el-radio-button><el-radio-button v-if="targetPlan?.billingCycles.includes('YEARLY')" value="YEARLY">年付</el-radio-button></el-radio-group><span>订单金额</span><strong>{{money(amount)}}</strong></div><el-alert v-if="!upgradePlans.length" type="warning" :closable="false" title="当前没有可升级的在线销售版本；商务报价版本请线下联系客户。"/><template v-else><el-alert type="info" :closable="false" title="管理端代客户提交升级订单，财务审核通过后权益自动生效。"/><div class="payment-fields"><el-input v-model="paidBy" placeholder="付款人（可选）"/><el-input v-model="paymentReference" placeholder="付款流水号（可选）"/></div><label class="upload-box"><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" hidden @change="pick"/><b>{{voucher?.name||(amount===0?'零元订单可不上传凭证':'点击选择付款凭证')}}</b><span>支持 JPG、PNG、WebP 或 PDF，最大 8 MB</span></label></template><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :disabled="!upgradePlans.length" :loading="submitting" @click="submitUpgrade">提交财务审核</el-button></template></el-dialog></div></template>
<style scoped>.toolbar{display:grid;grid-template-columns:minmax(260px,420px) 150px;gap:12px;margin-bottom:18px}.upgrade-summary{display:grid;grid-template-columns:92px 1fr;gap:14px 16px;align-items:center;margin-bottom:18px}.upgrade-summary>span{color:#66758a}.upgrade-summary strong{color:#1677ff;font-size:20px}.payment-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}.upload-box{display:grid;gap:5px;margin-top:12px;padding:18px;border:1px dashed #c5d2e5;border-radius:8px;text-align:center;cursor:pointer}.upload-box:hover{border-color:#409eff;background:#f5f9ff}.upload-box span{color:#8b98aa;font-size:12px}</style>
